        .await
        .expect("return timeout result")
        .into_inner();

    assert_eq!(response.exit_code, COMMAND_TIMEOUT_EXIT_CODE);
    assert!(response.stdout.is_empty());
    assert_eq!(response.stderr, b"command timed out\n");
}

